import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { createPortal } from 'react-dom';
import * as d3 from 'd3';
import './styles.css';
import './extra.css';
import './d3-map.css';
import './map-controls.css';
import './redwood.css';
import './contrast.css';
import './logs.css';
import './buttons.css';
import './markdown.css';

const api = async (path, options = {}) => {
  const response = await fetch(`api/${path}`, options);
  if (!response.ok) throw new Error(await response.text() || response.statusText);
  return response;
};
const json = (path, options) => api(path, options).then((r) => r.json());
const title = (value) => value.replaceAll('_', ' ').replace(/\b\w/g, (v) => v.toUpperCase());
const escape = (value) => String(value ?? '');
const downloadEndpoint = async (path, filename) => { const response = await api(path); const href = URL.createObjectURL(await response.blob()); const link = document.createElement('a'); link.href = href; link.download = filename; link.click(); URL.revokeObjectURL(href); };
const downloadMapArtifact = async (data, format) => { const response = await api('map-export', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ nodes: data.nodes, edges: data.edges, format }) }); const href = URL.createObjectURL(await response.blob()); const link = document.createElement('a'); link.href = href; link.download = `oci-iam-focused-map.${format}`; link.click(); URL.revokeObjectURL(href); };

function CellValue({ value }) {
  if (React.isValidElement(value)) return value;
  if (typeof value === 'object') return JSON.stringify(value);
  const [name, label] = String(value ?? '').split('\n');
  if (label === 'Administrator' || label === 'Domain administrator') return <span className="risk-user"><span>{name}</span><span className="administrator-badge">{label}</span></span>;
  return escape(value);
}

function DataTable({ rows, columns }) {
  if (!rows?.length) return <div className="empty">No matching records in this snapshot.</div>;
  const shown = columns || Object.keys(rows[0]);
  return <div className="table-wrap"><table><thead><tr>{shown.map((key) => <th key={key}>{title(key)}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={row.id || `${index}-${row.name || ''}`}>{shown.map((key) => <td key={key}><CellValue value={row[key]} /></td>)}</tr>)}</tbody></table></div>;
}

function Download({ label, value, filename }) {
  const download = () => { const blob = new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' }); const href = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = href; link.download = filename; link.click(); URL.revokeObjectURL(href); };
  return <button className="secondary" onClick={download}>{label}</button>;
}

function MultiSelect({ label, options, value, onChange, placeholder = 'Select items' }) {
  const [search, setSearch] = useState(''); const selected = options.filter((item) => value.includes(item.value)); const visible = options.filter((item) => item.label.toLowerCase().includes(search.toLowerCase()));
  const toggle = (item) => onChange(value.includes(item.value) ? value.filter((value) => value !== item.value) : [...value, item.value]);
  return <label className="multi-select">{label}<details><summary>{selected.length ? `${selected.length} selected · ${selected.slice(0, 2).map((item) => item.label).join(', ')}${selected.length > 2 ? '…' : ''}` : placeholder}</summary><div className="multi-options"><input className="multi-search" value={search} onChange={(event) => setSearch(event.target.value)} onClick={(event) => event.stopPropagation()} placeholder="Type to search…" autoComplete="off" />{visible.length ? visible.map((item) => <label key={item.value}><input type="checkbox" checked={value.includes(item.value)} onChange={() => toggle(item)} /> {item.label}</label>) : <p className="hint multi-empty">No matching options.</p>}</div></details></label>;
}

function Login({ onReady }) {
  const [username, setUsername] = useState('oci'); const [password, setPassword] = useState(''); const [error, setError] = useState('');
  const signIn = async (event) => { event.preventDefault(); setError(''); try { await json('login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username, password }) }); onReady(); } catch { setError('Invalid local username or password.'); } };
  return <main className="login-page"><section className="login-card"><h1>🛡️ OCI IAM Plotter</h1><form onSubmit={signIn}><label>Username<input value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username" /></label><label>Password<input value={password} onChange={(e) => setPassword(e.target.value)} type="password" autoComplete="current-password" /></label><button type="submit">Sign in</button>{error && <p className="error">{error}</p>}</form></section></main>;
}

function BucketCollections({ onSelected }) {
  const [records, setRecords] = useState([]); const [selected, setSelected] = useState(''); const [status, setStatus] = useState(''); const [loaded, setLoaded] = useState(false);
  const load = async () => { setStatus('Loading archived collections…'); try { const result = await json('bucket-snapshots'); setRecords(result.records || []); setStatus(result.error || (result.records?.length ? `${result.records.length} archived collections available.` : 'No archived collections found.')); setLoaded(true); } catch (error) { setStatus(error.message); } };
  const useSelected = async () => { if (!selected) return setStatus('Choose a bucket collection first.'); setStatus('Loading selected collection…'); try { await json('bucket-snapshots/select', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ object_name: selected }) }); setStatus('Selected collection loaded into the local five-snapshot cache.'); await onSelected(); } catch (error) { setStatus(error.message); } };
  return <details onToggle={(event) => event.currentTarget.open && !loaded && load()}><summary>Object Storage collections</summary><p className="hint">Durable archive in <b>bucket_iam_plotter</b>. Choose any retained tenancy collection to make it active.</p><label>Archived collection<select value={selected} onChange={(event) => setSelected(event.target.value)}><option value="">Select a bucket collection</option>{records.map((item) => <option key={item.object_name} value={item.object_name}>{item.tenancy_name} · {new Date(item.collected_at).toLocaleString()}</option>)}</select></label><div className="button-row"><button className="secondary" onClick={load}>Refresh list</button><button onClick={useSelected} disabled={!selected}>Use selected collection</button></div>{status && <p className="status">{status}</p>}</details>;
}

function Sidebar({ snapshot, history, tenancies, activeTenancy, onTenancy, refresh, onBucketSelected }) {
  const [config, setConfig] = useState(''); const [key, setKey] = useState(''); const [token, setToken] = useState(''); const [profile, setProfile] = useState('DEFAULT'); const [securityToken, setSecurityToken] = useState(false); const [status, setStatus] = useState(''); const [collectorOpen, setCollectorOpen] = useState(false); const [collapsed, setCollapsed] = useState(() => localStorage.getItem('oci-iam-plotter-sidebar') === 'collapsed');
  useEffect(() => localStorage.setItem('oci-iam-plotter-sidebar', collapsed ? 'collapsed' : 'open'), [collapsed]);
  const setupTemplate = securityToken ? `[DEFAULT]\ntenancy=ocid1.tenancy.oc1..example\nregion=us-chicago-1\nsecurity_token_file=/path/to/security_token` : `[DEFAULT]\ntenancy=ocid1.tenancy.oc1..example\nuser=ocid1.user.oc1..example\nfingerprint=aa:bb:cc:dd\nregion=us-chicago-1\nkey_file=/path/to/private_key.pem`;
  const copySetup = async () => { try { await navigator.clipboard.writeText(setupTemplate); setStatus('Setup template copied.'); } catch { setStatus('Copy is unavailable in this browser; select the template text and copy it manually.'); } };
  const collect = async () => { if (!config || !key || (securityToken && !token)) return setStatus(securityToken ? 'Provide config, security token, and private key.' : 'Provide both OCI config and private key.'); try { await json('collect', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ config_text: config, pem_text: key, profile_name: profile, use_security_token: securityToken, security_token_text: token }) }); setConfig(''); setKey(''); setToken(''); setStatus('Collection queued.'); const timer = setInterval(async () => { const job = await json('status'); setStatus(job.message); if (!['queued', 'running'].includes(job.status)) { clearInterval(timer); if (job.status === 'completed') refresh(); } }, 1800); } catch (error) { setStatus(error.message); } };
  const dialog = collectorOpen && createPortal(<div className="modal-backdrop collection-backdrop" onClick={() => setCollectorOpen(false)}><article className="modal collection-modal" onClick={(event) => event.stopPropagation()}><button className="modal-close" onClick={() => setCollectorOpen(false)} title="Close collection">×</button><span className="eyebrow">Collection</span><h3>Refresh IAM evidence</h3><p className="subtitle">This read-only tool collects IAM inventory, saves the normalized snapshot locally, and archives it to Object Storage. Supplied credentials are removed after the run.</p><details><summary>Config template and help</summary><p className="hint">Use an OCI API-signing profile, or select Security Token authentication and provide its matching key.</p><pre>{setupTemplate}</pre><button className="secondary" onClick={copySetup}>Copy template</button></details><label className="check-line"><input type="checkbox" checked={securityToken} onChange={(event) => setSecurityToken(event.target.checked)} /> Use Security Token authentication</label><label>OCI config<textarea value={config} onChange={(event) => setConfig(event.target.value)} placeholder="Paste OCI config" /></label>{securityToken && <label>Security token<textarea value={token} onChange={(event) => setToken(event.target.value)} placeholder="Paste security token content" /></label>}<label>{securityToken ? 'Security Token key' : 'API-signing private key'}<textarea value={key} onChange={(event) => setKey(event.target.value)} placeholder={securityToken ? 'Paste the security-token private key' : 'Paste PEM private key'} /></label>{securityToken && <p className="hint">The matching key signs the token request; it is not an API-signing credential and is deleted after collection.</p>}<label>OCI profile<input value={profile} onChange={(event) => setProfile(event.target.value)} /></label><div className="button-row"><button onClick={collect}>Collect snapshot</button><button className="secondary" onClick={() => setCollectorOpen(false)}>Cancel</button></div>{status && <p className="status">{status}</p>}</article></div>, document.body);
  return <>{dialog}<aside className={collapsed ? 'sidebar-collapsed' : ''}><div className="sidebar-heading"><div className="brand">◈ {!collapsed && <span>OCI IAM Plotter</span>}</div><button className="sidebar-toggle" onClick={() => setCollapsed((value) => !value)} title={collapsed ? 'Open sidebar' : 'Collapse sidebar'} aria-label={collapsed ? 'Open sidebar' : 'Collapse sidebar'}>{collapsed ? '›' : '‹'}</button></div>{!collapsed && <><small>Read-only local analysis</small>{tenancies.length > 0 && <label className="tenancy-picker">Active tenancy<select value={activeTenancy || ''} onChange={(event) => onTenancy(event.target.value)}>{tenancies.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.snapshot_count}/5 snapshots</option>)}</select><span className="hint">All sections use this tenancy’s latest snapshot.</span></label>}<section className="collection-launch"><b>Collection</b><p className="hint">Refresh read-only IAM evidence. Snapshots are archived securely.</p><button className="collect-action" onClick={() => setCollectorOpen(true)} title="Collect a read-only IAM snapshot">↻ Collect</button>{status && <p className="status">{status}</p>}</section><BucketCollections onSelected={onBucketSelected || refresh} />{snapshot && <details open><summary>Collection history · selected tenancy</summary><p className="hash">{snapshot.source_hash}</p>{history.map((item) => <p className="history" key={`${item.collected_at}-${item.source_hash}`}>{new Date(item.collected_at).toLocaleString()}</p>)}</details>}<details><summary>IAM terminology</summary><p className="hint"><b>Parsed</b> — standard Allow statement fields were extracted.</p><p className="hint"><b>Inferred</b> — evidence-backed lead, not OCI runtime authorization.</p><p className="hint"><b>RULE REFERENCES</b> — a dynamic rule points at a collected OCID or resource type.</p></details><footer>Secrets are never displayed. GenAI runs only when requested.</footer></>}</aside></>;
}

function Overview({ snapshot }) { const counts = snapshot.counts || {}; return <><div className="hero"><span className="eyebrow">Read-only identity intelligence</span><h1>OCI IAM Plotter</h1><p>Choose an identity, group, application, or policy and follow its evidence path through memberships, grants, rules, and scope—without changing cloud resources.</p></div><div className="metric-grid"><div className="metric active-user-metric"><strong>{snapshot.active_portal_users || 0}</strong><span>Users signed in now</span></div><div className="metric"><strong>{snapshot.stored_users || 0}</strong><span>Collected IAM users</span></div><div className="metric"><strong>{snapshot.active_users || 0}</strong><span>Active IAM users</span></div>{['group', 'dynamic_group', 'policy', 'confidential_app', 'oauth_app', 'compartment', 'domain'].map((kind) => <div className="metric" key={kind}><strong>{counts[kind] || 0}</strong><span>{title(kind)}</span></div>)}</div><div className="notice">Users signed in now counts active application sessions in this hosted-app process. Collected IAM users and active IAM users come from the selected tenancy snapshot.</div></>; }

function Investigate({ entities }) {
  const categories = [...new Set(entities.map((item) => item.kind))].sort(); const [kinds, setKinds] = useState(['user', 'group', 'domain_user', 'domain_group', 'confidential_app', 'dynamic_group']); const [selected, setSelected] = useState([]); const [depth, setDepth] = useState(1); const [map, setMap] = useState(null); const [relationFilter, setRelationFilter] = useState([]); const [error, setError] = useState(''); const available = entities.filter((item) => kinds.includes(item.kind) || selected.includes(item.id));
  const run = async () => { if (!selected.length) return setError('Select at least one subject.'); try { const payload = await json('investigate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ focus_ids: selected, depth, relations: relationFilter.length ? relationFilter : null, max_edges: 32 }) }); setMap(payload); setRelationFilter(payload.available_relations); setError(''); } catch (value) { setError(value.message); } };
  return <section><h2>Focused access investigation <span title="A capped one- or two-hop view around selected entities.">ⓘ</span></h2><p className="subtitle">Choose multiple entity categories and subjects, then explore a focused evidence map instead of a tenancy-wide graph.</p><div className="flow"><div><b>1 · Choose</b>Filter users, groups, domains, apps, policies, or dynamic groups.</div><div><b>2 · Correlate</b>Select multiple subjects and relationship evidence.</div><div><b>3 · Verify</b>Zoom, maximize, open separately, and inspect details.</div></div><div className="controls"><MultiSelect label="Entity categories" value={kinds} onChange={setKinds} options={categories.map((item) => ({ value: item, label: title(item) }))} placeholder="Select categories" /><MultiSelect label="Matching subjects" value={selected} onChange={setSelected} options={available.map((item) => ({ value: item.id, label: `${item.name} · ${title(item.kind)}` }))} placeholder="Select subjects" /><label>Depth<select value={depth} onChange={(e) => setDepth(Number(e.target.value))}><option value={1}>One hop</option><option value={2}>Two hops</option></select></label><button onClick={run}>Build map</button></div>{map && <div className="relation-chips">{map.available_relations.map((item) => <label key={item}><input type="checkbox" checked={relationFilter.includes(item)} onChange={(e) => setRelationFilter(e.target.checked ? [...relationFilter, item] : relationFilter.filter((value) => value !== item))} /> {title(item)}</label>)}</div>}{error && <p className="error">{error}</p>}{map && <Map data={map} />}</section>;
}

function D3MapCanvas({ data, maximized, layout }) { const svgRef = useRef(null); const controls = useRef(null); useEffect(() => { const width = maximized ? 1600 : 1120, height = maximized ? 860 : 610, colors = { user: '#2f80ed', domain_user: '#2f80ed', group: '#21a179', domain_group: '#21a179', domain: '#b35aa7', dynamic_group: '#8b5cf6', policy: '#ef8b3c', confidential_app: '#e75b76', oauth_app: '#e75b76', compartment: '#1b9aaa' }; const nodes = data.nodes.map((item) => ({ ...item })); const byId = new globalThis.Map(nodes.map((item) => [item.id, item])); const links = data.edges.filter((item) => byId.has(item.source) && byId.has(item.target)).map((item) => ({ ...item, source: byId.get(item.source), target: byId.get(item.target) })); const svg = d3.select(svgRef.current).attr('viewBox', `0 0 ${width} ${height}`); svg.selectAll('*').remove(); svg.append('defs').append('marker').attr('id', 'd3-arrow').attr('viewBox', '0 -7 14 14').attr('refX', 88).attr('refY', 0).attr('markerWidth', 11).attr('markerHeight', 11).attr('orient', 'auto').append('path').attr('class', 'd3-arrowhead').attr('d', 'M0,-7L14,0L0,7').attr('fill', '#f5c451'); const stage = svg.append('g'); const typeOrder = [...new Set(nodes.map((item) => item.kind))]; const x = d3.scalePoint(typeOrder, [130, width - 130]); if (layout === 'cluster') stage.append('g').selectAll('text').data(typeOrder).join('text').attr('class', 'cluster-label').attr('x', (item) => x(item)).attr('y', 32).text((item) => title(item)); const link = stage.append('g').attr('class', 'd3-links').selectAll('path').data(links).join('path').attr('class', (item) => /rule|infer/.test(item.evidence || '') ? 'inferred' : '').attr('marker-end', 'url(#d3-arrow)'); const linkLabel = stage.append('g').selectAll('text').data(links).join('text').attr('class', 'd3-link-label').text((item) => item.relation.replaceAll('_', ' ')); let simulation; const node = stage.append('g').selectAll('g').data(nodes).join('g').attr('class', 'd3-node').call(d3.drag().on('start', (event, item) => { if (!event.active) simulation.alphaTarget(.25).restart(); item.fx = item.x; item.fy = item.y; }).on('drag', (event, item) => { item.fx = event.x; item.fy = event.y; }).on('end', (event, item) => { if (!event.active) simulation.alphaTarget(0); item.fx = null; item.fy = null; })); node.append('rect').attr('width', 154).attr('height', 58).attr('x', -77).attr('y', -29).attr('rx', 13).attr('fill', (item) => data.focus_ids.includes(item.id) ? '#063d4c' : colors[item.kind] || '#526273').attr('stroke', (item) => data.focus_ids.includes(item.id) ? '#f5c451' : '#d8efff').attr('stroke-width', (item) => data.focus_ids.includes(item.id) ? 3 : 1.2); node.append('text').attr('class', 'd3-node-label').attr('y', -3).text((item) => item.label.length > 21 ? `${item.label.slice(0, 20)}…` : item.label); node.append('text').attr('class', 'd3-node-kind').attr('y', 15).text((item) => title(item.kind)); const base = d3.forceSimulation(nodes).force('link', d3.forceLink(links).id((item) => item.id).distance(layout === 'hierarchy' ? 210 : 165).strength(.85)).force('charge', d3.forceManyBody().strength(-780)).force('collide', d3.forceCollide(92)); simulation = layout === 'radial' ? base.force('radial', d3.forceRadial((item) => data.focus_ids.includes(item.id) ? 0 : 210, width / 2, height / 2).strength(.45)).force('center', d3.forceCenter(width / 2, height / 2)) : layout === 'hierarchy' ? base.force('x', d3.forceX((item) => data.focus_ids.includes(item.id) ? 170 : width * .62).strength(.32)).force('y', d3.forceY((item) => item.data?.focus_ids ? height / 2 : height / 2).strength(.08)) : base.force('x', d3.forceX((item) => x(item.kind)).strength(.23)).force('y', d3.forceY(height / 2).strength(.08)); simulation.on('tick', () => { link.attr('d', (item) => { const dx = item.target.x - item.source.x, dy = item.target.y - item.source.y, bend = Math.min(55, Math.hypot(dx, dy) / 3); return `M${item.source.x},${item.source.y}Q${(item.source.x + item.target.x) / 2 - dy / 10},${(item.source.y + item.target.y) / 2 + dx / 10 + bend},${item.target.x},${item.target.y}`; }); linkLabel.attr('x', (item) => (item.source.x + item.target.x) / 2).attr('y', (item) => (item.source.y + item.target.y) / 2 - 6); node.attr('transform', (item) => `translate(${item.x},${item.y})`); }); const zoom = d3.zoom().scaleExtent([.35, 2.8]).on('zoom', (event) => stage.attr('transform', event.transform)); svg.call(zoom); controls.current = { in: () => svg.transition().call(zoom.scaleBy, 1.25), out: () => svg.transition().call(zoom.scaleBy, .8), home: () => svg.transition().call(zoom.transform, d3.zoomIdentity) }; return () => simulation.stop(); }, [data, maximized, layout]); return <><div className="map-tools"><button className="secondary" onClick={() => controls.current?.in()}>＋</button><button className="secondary" onClick={() => controls.current?.out()}>−</button><button className="secondary" onClick={() => controls.current?.home()}>Home</button></div><svg ref={svgRef} className="d3-canvas" /></>; }
function TreeMapCanvas({ data, maximized }) {
  const svgRef = useRef(null); const controls = useRef(null); const [collapsed, setCollapsed] = useState([]);
  useEffect(() => {
    const width = maximized ? 1600 : 1120, height = maximized ? 860 : 610;
    const colors = { user: '#2f80ed', domain_user: '#2f80ed', group: '#21a179', domain_group: '#21a179', domain: '#b35aa7', dynamic_group: '#8b5cf6', policy: '#ef8b3c', confidential_app: '#e75b76', oauth_app: '#e75b76', compartment: '#1b9aaa' };
    const records = new globalThis.Map(data.nodes.map((item) => [item.id, { ...item, children: [] }])); const neighbours = new globalThis.Map(data.nodes.map((item) => [item.id, []]));
    data.edges.forEach((edge) => { if (records.has(edge.source) && records.has(edge.target)) { neighbours.get(edge.source).push(edge.target); neighbours.get(edge.target).push(edge.source); } });
    const roots = (data.focus_ids || []).filter((id) => records.has(id)); if (!roots.length && data.nodes[0]) roots.push(data.nodes[0].id);
    const seen = new Set(roots); const queue = [...roots]; while (queue.length) { const id = queue.shift(); neighbours.get(id).forEach((child) => { if (!seen.has(child)) { seen.add(child); records.get(id).children.push(records.get(child)); queue.push(child); } }); }
    records.forEach((item, id) => { if (!seen.has(id)) roots.push(id); }); const root = d3.hierarchy({ id: '__root__', children: roots.map((id) => records.get(id)) });
    root.eachBefore((item) => { if (collapsed.includes(item.data.id)) item.children = null; }); d3.tree().nodeSize([92, 220])(root);
    const svg = d3.select(svgRef.current).attr('viewBox', `0 0 ${width} ${height}`); svg.selectAll('*').remove(); const stage = svg.append('g').attr('transform', 'translate(100,70)');
    const visible = root.descendants().filter((item) => item.data.id !== '__root__'); const links = root.links().filter((item) => item.source.data.id !== '__root__');
    stage.append('g').attr('class', 'd3-links').selectAll('path').data(links).join('path').attr('d', (item) => `M${item.source.y},${item.source.x}C${item.source.y + 80},${item.source.x} ${item.target.y - 80},${item.target.x} ${item.target.y},${item.target.x}`);
    const node = stage.append('g').selectAll('g').data(visible).join('g').attr('class', 'd3-node').attr('transform', (item) => `translate(${item.y},${item.x})`).on('click', (event, item) => { event.stopPropagation(); if (item.data.children?.length) setCollapsed((value) => value.includes(item.data.id) ? value.filter((id) => id !== item.data.id) : [...value, item.data.id]); });
    node.append('rect').attr('width', 166).attr('height', 60).attr('x', -83).attr('y', -30).attr('rx', 13).attr('fill', (item) => data.focus_ids.includes(item.data.id) ? '#063d4c' : colors[item.data.kind] || '#526273').attr('stroke', (item) => data.focus_ids.includes(item.data.id) ? '#f5c451' : '#d8efff').attr('stroke-width', 1.5);
    node.append('text').attr('class', 'd3-node-label').attr('y', -4).text((item) => item.data.label.length > 22 ? `${item.data.label.slice(0, 21)}…` : item.data.label); node.append('text').attr('class', 'd3-node-kind').attr('y', 15).text((item) => `${title(item.data.kind)}${item.data.children?.length ? (collapsed.includes(item.data.id) ? ' · +' : ' · −') : ''}`);
    const zoom = d3.zoom().scaleExtent([.35, 2.8]).on('zoom', (event) => stage.attr('transform', event.transform)); svg.call(zoom); controls.current = { in: () => svg.transition().call(zoom.scaleBy, 1.25), out: () => svg.transition().call(zoom.scaleBy, .8), home: () => svg.transition().call(zoom.transform, d3.zoomIdentity) };
  }, [data, maximized, collapsed]);
  return <><div className="map-tools"><button className="secondary" onClick={() => controls.current?.in()}>＋</button><button className="secondary" onClick={() => controls.current?.out()}>−</button><button className="secondary" onClick={() => controls.current?.home()}>Home</button><button className="secondary" onClick={() => setCollapsed([])}>Expand all</button></div><svg ref={svgRef} className="d3-canvas tree-canvas" /></>;
}
function Map({ data, standalone = false }) { const [maximized, setMaximized] = useState(false); const [layout, setLayout] = useState('cluster'); const openMapOnly = () => { localStorage.setItem('oci-iam-plotter-active-map', JSON.stringify(data)); window.open(`${window.location.pathname}?mapOnly=1`, '_blank', 'noopener'); }; return <><div className={maximized ? 'map-modal' : 'map-area'}><div className="map-caption">Arrows show relationship direction · drag the background to pan · scroll to zoom · {layout === 'tree' ? 'click a branch to collapse or expand it' : 'drag nodes to refine the layout'}</div><div className="map-tools"><label>Map layout<select value={layout} onChange={(event) => setLayout(event.target.value)}><option value="cluster">Evidence clusters</option><option value="hierarchy">Left-to-right hierarchy</option><option value="tree">Expandable evidence tree</option></select></label></div><div className="map-legend"><span className="legend-user">Users</span><span className="legend-group">Groups</span><span className="legend-domain">Domains</span><span className="legend-policy">Policies</span><span className="legend-app">Apps</span><span className="legend-dynamic">Dynamic groups</span></div>{layout === 'tree' ? <TreeMapCanvas data={data} maximized={maximized || standalone} /> : <D3MapCanvas data={data} maximized={maximized || standalone} layout={layout} />}{!standalone && <><button className="secondary" onClick={() => setMaximized(!maximized)}>{maximized ? 'Exit full map' : 'Maximize map'}</button><button className="secondary" onClick={openMapOnly}>Open map in new tab</button></>}{maximized && <button className="modal-close" onClick={() => setMaximized(false)}>×</button>}</div>{!standalone && <><div className="button-row"><Download label="Download map JSON" value={data} filename="oci-iam-focused-map.json" /><button className="secondary" onClick={() => downloadMapArtifact(data, 'png')}>Download map image</button><button className="secondary" onClick={() => downloadMapArtifact(data, 'pdf')}>Download map PDF</button></div><details><summary>Selected entity details</summary><pre>{JSON.stringify(data.details, null, 2)}</pre></details></>}</>; }

function Inventory({ snapshot, entities }) { const [kind, setKind] = useState(''); const [search, setSearch] = useState(''); const [rows, setRows] = useState(entities); const apply = async (nextKind = kind) => { const query = new URLSearchParams({ kind: nextKind, search }); const result = await json(`inventory?${query}`); setRows(result.entities); setKind(nextKind); }; return <section><h2>Inventory</h2><Overview snapshot={snapshot} /><p className="subtitle">Click an inventory count to filter the evidence table; remove the filter at any time.</p><div className="metric-grid clickable-metrics">{Object.entries(snapshot.counts).map(([name, value]) => <button className={kind === name ? 'metric selected' : 'metric'} onClick={() => apply(name)} key={name}><strong>{value}</strong><span>{title(name)}</span></button>)}</div><div className="controls"><label>Search inventory<input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Name, OCID, description…" /></label><label>Entity type<select value={kind} onChange={(e) => setKind(e.target.value)}><option value="">All types</option>{[...new Set(entities.map((item) => item.kind))].sort().map((item) => <option key={item}>{title(item)}</option>)}</select></label><button onClick={() => apply()}>Apply filter</button><button className="secondary" onClick={() => { setKind(''); setSearch(''); setRows(entities); }}>Remove filters</button><button className="secondary" onClick={() => downloadEndpoint(`inventory/export?${new URLSearchParams({ kind, search })}`, 'oci-iam-filtered-inventory.xlsx')}>Download Excel</button></div><p className="subtitle">{rows.length} filtered entities</p><DataTable rows={rows} columns={['name', 'kind', 'id', 'lifecycle_state', 'description', 'compartment_id']} /><details><summary>Snapshot metadata and download</summary><pre>{JSON.stringify({ tenancy_id: snapshot.tenancy_id, collected_at: snapshot.collected_at, source_hash: snapshot.source_hash, warnings: snapshot.warnings }, null, 2)}</pre><a href="api/snapshot/download">Download normalized snapshot</a></details></section>; }

function Users({ entities }) { const users = entities.filter((item) => item.kind === 'user'); const [id, setId] = useState(users[0]?.id || ''); const [result, setResult] = useState(null); const run = () => json(`user-analysis/${encodeURIComponent(id)}`).then(setResult); return <section><h2>User analysis</h2><div className="controls"><label>Select user<select value={id} onChange={(e) => setId(e.target.value)}>{users.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><button onClick={run}>Analyze cached evidence</button></div>{result && <><div className="metric-grid"><div className="metric"><strong>{result.groups.length}</strong><span>Groups</span></div><div className="metric"><strong>{result.applicable_policy_statements.length}</strong><span>Matching statements</span></div><div className="metric"><strong>{result.implied_permissions.length}</strong><span>Permission summaries</span></div><div className="metric"><strong>{result.unresolved_ambiguous_statements.length}</strong><span>Ambiguous</span></div></div><h3>Group membership</h3><DataTable rows={result.groups} columns={['name', 'id', 'lifecycle_state']} /><h3>Inferred permissions</h3><div>{result.implied_permissions.map((item) => <span className="pill" key={item}>{item}</span>) || 'No standard group policy statements matched.'}</div><h3>Matching policy evidence</h3><DataTable rows={result.applicable_policy_statements} columns={['principal_name', 'verb', 'resource_type', 'scope', 'condition', 'original_text']} /><p className="notice">{result.limitations.join(' ')}</p><Download label="Download user analysis JSON" value={result} filename="oci-iam-user-analysis.json" /></>}</section>; }

function Policies() { const [query, setQuery] = useState(''); const [result, setResult] = useState(null); const run = () => json(`policy-statements?search=${encodeURIComponent(query)}`).then(setResult); return <section><h2>Policy statements</h2><div className="controls"><label>Filter policy statements<input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="group, resource type, verb, scope…" /></label><button onClick={run}>Search</button><button className="secondary" onClick={() => downloadEndpoint(`policy-statements/export?search=${encodeURIComponent(query)}`, 'oci-iam-filtered-policy-statements.xlsx')}>Download filtered Excel</button></div>{result && <><p className="subtitle">{result.statements.length} visible · {result.parsed} parsed · {result.statements.length - result.parsed} ambiguous</p><DataTable rows={result.statements} columns={['policy', 'principal_type', 'principal_name', 'verb', 'resource_type', 'scope', 'condition', 'confidence', 'original_text']} /></>}</section>; }

function Duplicates() { const [result, setResult] = useState(null); const [detail, setDetail] = useState(null); useEffect(() => { json('duplicates').then(setResult); }, []); if (!result) return <section><h2>Duplicates</h2><div className="empty">Comparing normalized names and policy text…</div></section>; const near = result.near_entity_name_candidates.map((item, index) => ({ ...item, view: <button className="icon" onClick={() => setDetail(item)} title="View candidate evidence">◉</button>, key: index })); return <section><h2>Duplicate candidates</h2><div className="metric-grid"><div className="metric"><strong>{result.exact_entity_name_candidates.length}</strong><span>Exact entity names</span></div><div className="metric"><strong>{result.exact_policy_statement_candidates.length}</strong><span>Exact statements</span></div><div className="metric"><strong>{result.near_entity_name_candidates.length}</strong><span>Near-name candidates</span></div></div><p className="notice">{result.note}</p><div className="button-row"><button className="secondary" onClick={() => downloadEndpoint('duplicates/export', 'oci-iam-duplicate-candidates.xlsx')}>Download candidates Excel</button></div><h3>Near-name candidates</h3><DataTable rows={near} columns={['kind', 'left', 'right', 'similarity', 'view']} /><details><summary>Exact entity-name candidates</summary><DataTable rows={result.exact_entity_name_candidates.flat()} /></details>{detail && <div className="modal-backdrop" onClick={() => setDetail(null)}><article className="modal" onClick={(e) => e.stopPropagation()}><button className="modal-close" onClick={() => setDetail(null)}>×</button><h3>Candidate evidence</h3><p><b>Similarity:</b> {detail.similarity}</p><h4>{detail.left.name}</h4><pre>{JSON.stringify(detail.left, null, 2)}</pre><h4>{detail.right.name}</h4><pre>{JSON.stringify(detail.right, null, 2)}</pre></article></div>}</section>; }

function Drift() { const [collections, setCollections] = useState([]); const [baseline, setBaseline] = useState(''); const [current, setCurrent] = useState(''); const [result, setResult] = useState(null); const [error, setError] = useState(''); useEffect(() => { json('drift/collections').then(({ records, error: archiveError }) => { setCollections(records); setCurrent(records[0]?.id || ''); setBaseline(records[1]?.id || ''); setError(archiveError || ''); }).catch((err) => setError(err.message)); }, []); const compare = () => json('drift', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ baseline, current }) }).then(setResult).catch((err) => setError(err.message)); const label = (item) => `${new Date(item.collected_at).toLocaleString()} · ${item.source === 'bucket' ? 'Object Storage' : 'Local cache'}`; return <section><h2>IAM drift</h2><p className="subtitle">Compare same-tenancy local or Object Storage collections. OCI IDs are the identity keys.</p>{error && <p className="notice">{error}</p>}{collections.length < 2 ? <div className="empty">No second collection is available yet. Archived Object Storage collections appear here automatically after collection completes.</div> : <><div className="controls"><label>Current collection<select value={current} onChange={(e) => setCurrent(e.target.value)}>{collections.map((item) => <option key={item.id} value={item.id}>{label(item)}</option>)}</select></label><label>Baseline collection<select value={baseline} onChange={(e) => setBaseline(e.target.value)}>{collections.map((item) => <option key={item.id} value={item.id}>{label(item)}</option>)}</select></label><button onClick={compare} disabled={!baseline || !current || baseline === current}>Compare collections</button></div>{result && <><div className="metric-grid">{Object.entries(result.counts).map(([key, count]) => <div className="metric" key={key}><strong>{count.added + count.removed + count.changed}</strong><span>{title(key)} · +{count.added} / −{count.removed} / ~{count.changed}</span></div>)}</div><p className="notice">{result.unchanged ? 'No collected IAM inventory changes were found.' : 'Collected IAM changes found. Review original evidence before acting.'}</p><Download label="Download IAM drift report" value={result} filename="oci-iam-drift-report.json" /></>}</>}</section>; }

function Reports({ entities }) { const [users, setUsers] = useState([]); const [includeSummary, setIncludeSummary] = useState(true); const [busy, setBusy] = useState(false); const [result, setResult] = useState(null); const [error, setError] = useState(''); const requestBody = (format) => ({ user_ids: users, format, include_summary: includeSummary }); const build = async () => { setBusy(true); setError(''); try { setResult(await json('report', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(requestBody('json')) })); } catch (err) { setError(err.message); } finally { setBusy(false); } }; const download = async (format) => { setBusy(true); try { const r = await api('report', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(requestBody(format)) }); if (!r.ok) throw new Error(await r.text()); const blob = await r.blob(); const link = document.createElement('a'); const url = URL.createObjectURL(blob); link.href = url; link.download = `oci-iam-risk-report.${format === 'markdown' ? 'md' : format}`; link.click(); URL.revokeObjectURL(url); } catch (err) { setError(err.message); } finally { setBusy(false); } }; const posture = result?.risk_posture; return <section><h2>Access risk report</h2><p className="subtitle">Build a real analysis from the active collected snapshot. It maps users to their groups and matching policy text, then prioritizes broad or sensitive permissions. Empty selection analyzes every collected user.</p><div className="controls"><MultiSelect label="Users to analyze" value={users} onChange={setUsers} options={entities.filter((item) => item.kind === 'user').map((item) => ({ value: item.id, label: item.name }))} placeholder="All collected users" /><label className="report-summary-toggle"><input type="checkbox" checked={includeSummary} onChange={(event) => setIncludeSummary(event.target.checked)} /> Include OCI GenAI summaries</label><button onClick={build} disabled={busy}>{busy ? 'Building…' : 'Build report'}</button></div>{error && <p className="error">{error}</p>}{result && <div className="report-preview"><div className="report-preview-head"><div><span className="eyebrow">Generated report</span><h3>Access risk posture</h3></div><div className="button-row"><button className="secondary" onClick={() => download('pdf')} disabled={busy}>Download PDF</button><button className="secondary" onClick={() => download('markdown')} disabled={busy}>Download Markdown</button></div></div><p className="notice">{posture.method}</p><div className="metric-grid risk-metrics">{Object.entries(posture.distribution).map(([level, count]) => <div className={`metric risk-${level}`} key={level}><strong>{count}</strong><span>{title(level)} risk users</span></div>)}</div><h3>Users needing priority review</h3>{posture.flagged_users.length ? <DataTable rows={posture.flagged_users.map((item) => ({ user: item.name, risk: item.risk_level, score: item.risk_score, signals: item.signals.map((signal) => signal.permission).join('; ') }))} columns={['user', 'risk', 'score', 'signals']} /> : <div className="empty compact">No high or critical heuristic signals were found in the matched standard group policies.</div>}<h3>Per-user evidence</h3><DataTable rows={result.access_analyses.map((item) => ({ user: item.user.name, groups: item.groups.map((group) => group.name).join(', ') || 'None', risk: item.risk.level, score: item.risk.score, matching_policies: item.applicable_policy_statements.length, implied_permissions: item.implied_permissions.join('; ') || 'None matched' }))} columns={['user', 'groups', 'risk', 'score', 'matching_policies', 'implied_permissions']} />{result.summaries.length > 0 && <details><summary>OCI Generative AI summaries</summary>{result.summaries.map((item) => <article className="ai-summary" key={item.user_id}><b>{item.user_name}</b><p>{item.summary}</p><small>Source: {item.source}</small></article>)}</details>}<p className="notice">This is a policy-text prioritization report, not proof of effective authorization. Review policy conditions, inheritance, and OCI service evaluation before acting.</p></div>}</section>; }

function Ask() { const [question, setQuestion] = useState(''); const [answer, setAnswer] = useState(null); const run = () => json('ask', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ question }) }).then(setAnswer); return <section><h2>Ask IAM</h2><p className="subtitle">Retrieve compact evidence from the cached snapshot without making a new OCI request.</p><div className="controls"><label>Question<input value={question} onChange={(e) => setQuestion(e.target.value)} placeholder="Who has access to buckets?" /></label><button onClick={run}>Ask IAM</button></div>{answer && <><div className="answer">{answer.answer}</div><details><summary>Retrieved evidence</summary><pre>{JSON.stringify(answer.evidence, null, 2)}</pre></details></>}</section>; }

function ChatPopup() { const [open, setOpen] = useState(false); const [question, setQuestion] = useState(''); const [messages, setMessages] = useState([]); const [busy, setBusy] = useState(false); const send = async (event) => { event.preventDefault(); if (!question.trim() || busy) return; const prompt = question.trim(); const history = messages.slice(-6).map(({ role, text }) => ({ role, text })); setQuestion(''); setMessages((items) => [...items, { role: 'user', text: prompt }]); setBusy(true); try { const result = await json('ask', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ question: prompt, history }) }); setMessages((items) => [...items, { role: 'assistant', text: result.answer, evidence: result.evidence, agent: result.agent }]); } catch (error) { setMessages((items) => [...items, { role: 'assistant', text: error.message }]); } finally { setBusy(false); } }; return <div className="chat-dock"><button className="chat-launch" onClick={() => setOpen(!open)} title={open ? 'Close Ask IAM' : 'Open Ask IAM'}>{open ? 'Close' : 'Ask IAM'}</button>{open && <section className="chat-window"><header><b>Ask IAM</b><span>Evidence agent · cached snapshot</span></header><div className="chat-history">{messages.length === 0 && <p className="hint">Ask about users, groups, policy statements, applications, drift, or duplicate candidates.</p>}{messages.map((message, index) => <div key={index} className={`message ${message.role}`}><div>{message.text}</div>{message.agent && <details><summary>Agent run · {message.agent.tools.join(' → ')}</summary><pre>{JSON.stringify(message.agent, null, 2)}</pre></details>}{message.evidence && <details><summary>Evidence</summary><pre>{JSON.stringify(message.evidence, null, 2)}</pre></details>}</div>)}{busy && <div className="message assistant">Planning read-only evidence tools…</div>}</div><form onSubmit={send}><input value={question} onChange={(e) => setQuestion(e.target.value)} placeholder="Ask a follow-up question…" /><button type="submit">Ask</button></form></section>}</div>; }

function CollectionLogs() { const [logs, setLogs] = useState([]); const [status, setStatus] = useState('idle'); const load = async () => { const result = await json('collection-logs'); setLogs(result.events); setStatus(result.status); }; useEffect(() => { load(); const timer = setInterval(load, 1800); return () => clearInterval(timer); }, []); return <section><h2>Collection logs</h2><p className="subtitle">Credential-safe progress from the latest collection. The log records read scopes and counts, never OCI configuration, PEM material, tokens, or signer details.</p><div className="log-toolbar"><span className={`log-state ${status}`}>{title(status)}</span><button className="secondary" onClick={load}>Refresh</button><Download label="Download log JSON" value={logs} filename="oci-iam-collection-log.json" /></div><div className="log-list">{logs.length ? logs.map((event, index) => <div className={`log-entry ${event.level}`} key={`${event.time}-${index}`}><time>{new Date(event.time).toLocaleTimeString()}</time><span>{event.message}</span></div>) : <div className="empty">No collection has run in this application process yet.</div>}</div></section>; }

function RiskPosture() { const [result, setResult] = useState(null); const [error, setError] = useState(''); const load = () => json('risk-posture').then(setResult).catch((err) => setError(err.message)); useEffect(() => { load(); }, []); if (!result) return <section><h2>Tenancy risk posture</h2>{error ? <p className="error">{error}</p> : <div className="empty compact">Analyzing all collected users and group-policy evidence…</div>}</section>; return <section><div className="report-preview-head"><div><span className="eyebrow">All collected users</span><h2>Tenancy risk posture</h2></div><button className="secondary" onClick={load}>Refresh posture</button></div><p className="notice">{result.method} Tenancy-wide <code>inspect</code> is treated as expected inventory access for compartment navigation and is excluded from findings.</p><div className="metric-grid">{Object.entries(result.distribution).map(([level, count]) => <div className={`metric risk-${level}`} key={level}><strong>{count}</strong><span>{title(level)} risk users</span></div>)}</div><h3>Latest top 20 risk signals</h3>{result.top_risk_elements.length ? <DataTable rows={result.top_risk_elements.map((item) => ({ user: item.user, risk: item.level, score: item.score, permission: item.permission, why: item.reasons.join('; ') }))} columns={['user', 'risk', 'score', 'permission', 'why']} /> : <div className="empty compact">No medium, high, or critical policy-risk signals were found.</div>}<p className="notice">Potential IAM administration or indirect privilege-escalation signals are highlighted for review, not asserted as effective access.</p></section>; }

function PerUserReports({ entities }) { const [users, setUsers] = useState([]); const [includeSummary, setIncludeSummary] = useState(true); const [result, setResult] = useState(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const build = async () => { if (!users.length) return; setBusy(true); setError(''); try { setResult(await json('report', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user_ids: users, format: 'json', include_summary: includeSummary, archive: true }) })); } catch (err) { setError(err.message); } finally { setBusy(false); } }; const download = async (format) => { const response = await api('report', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user_ids: users, format, include_summary: includeSummary, archive: false }) }); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `oci-iam-user-report.${format === 'markdown' ? 'md' : format}`; link.click(); URL.revokeObjectURL(url); }; return <section><h2>Per-user reports</h2><p className="subtitle">Select one or more users to create a saved, evidence-based report. The tenancy-wide posture is kept separately in its own subtab.</p><div className="controls"><MultiSelect label="Users" value={users} onChange={setUsers} options={entities.filter((item) => item.kind === 'user').map((item) => ({ value: item.id, label: item.name }))} placeholder="Choose users" /><label><input type="checkbox" checked={includeSummary} onChange={(event) => setIncludeSummary(event.target.checked)} /> Include OCI GenAI summaries</label><button onClick={build} disabled={!users.length || busy}>{busy ? 'Building…' : 'Build per-user report'}</button></div>{error && <p className="error">{error}</p>}{result && <div className="report-preview"><div className="report-preview-head"><h3>Generated per-user report</h3><div className="button-row"><button className="secondary" onClick={() => download('pdf')}>Download PDF</button><button className="secondary" onClick={() => download('markdown')}>Download Markdown</button></div></div><DataTable rows={result.access_analyses.map((item) => ({ user: item.user.name, groups: item.groups.map((group) => group.name).join(', ') || 'None', risk: item.risk.level, policies: item.applicable_policy_statements.length, access: item.implied_permissions.join('; ') || 'No matching policy' }))} columns={['user', 'groups', 'risk', 'policies', 'access']} />{result.summaries.length ? <details><summary>OCI Generative AI summaries</summary>{result.summaries.map((item) => <article className="ai-summary" key={item.user_id}><b>{item.user_name}</b><p>{item.summary}</p></article>)}</details> : null}</div>}</section>; }

function ReportCenter({ entities }) { const [tab, setTab] = useState('Per-user reports'); return <><div className="report-subtabs"><button className={tab === 'Per-user reports' ? 'active' : 'secondary'} onClick={() => setTab('Per-user reports')}>Per-user reports</button><button className={tab === 'Risk posture' ? 'active' : 'secondary'} onClick={() => setTab('Risk posture')}>Risk posture</button></div>{tab === 'Per-user reports' ? <><PerUserReports entities={entities} /><ReportArchive /></> : <RiskPosture />}</>; }

function ReportArchive() { const [records, setRecords] = useState([]); const [error, setError] = useState(''); const [selected, setSelected] = useState(null); const load = () => json('reports/archive').then((data) => { setRecords(data.records || []); setError(data.error || ''); }).catch((err) => setError(err.message)); useEffect(() => { load(); }, []); const open = (name) => json(`reports/archive/load?object_name=${encodeURIComponent(name)}`).then(setSelected).catch((err) => setError(err.message)); return <section className="report-archive"><div className="report-preview-head"><div><span className="eyebrow">Object Storage</span><h3>Saved risk reports</h3></div><button className="secondary" onClick={load}>Refresh</button></div><p className="subtitle">Latest five reports for this tenancy. A new report is saved when you build it.</p>{error && <p className="error">{error}</p>}{records.length ? <DataTable rows={records.map((record, index) => ({ latest: index === 0 ? 'Latest' : '', created: new Date(record.created_at).toLocaleString(), report: <button className="secondary" onClick={() => open(record.object_name)}>Open</button> }))} columns={['latest', 'created', 'report']} /> : <div className="empty compact">No saved reports are available yet.</div>}{selected && <details open><summary>Saved report preview</summary><p className="notice">{selected.risk_posture?.method}</p><DataTable rows={(selected.risk_posture?.top_risk_elements || []).map((item) => ({ user: item.user, risk: item.level, score: item.score, permission: item.permission, why: item.reasons.join('; ') }))} columns={['user', 'risk', 'score', 'permission', 'why']} /></details>}</section>; }

function Workspace({ snapshot, entities, history, tenancies, activeTenancy, onTenancy, refresh, signOut }) { const tabs = ['Access Map', 'Inventory', 'IAM drift', 'User analysis', 'Policy statements', 'Duplicates', 'Reports', 'Collection logs']; const [tab, setTab] = useState('Access Map'); const views = { 'Access Map': <Investigate entities={entities} />, Inventory: <Inventory snapshot={snapshot} entities={entities} />, 'IAM drift': <Drift />, 'User analysis': <Users entities={entities} />, 'Policy statements': <Policies />, Duplicates: <Duplicates />, Reports: <ReportCenter entities={entities} />, 'Collection logs': <CollectionLogs /> }; return <div className="shell"><Sidebar snapshot={snapshot} history={history} tenancies={tenancies} activeTenancy={activeTenancy} onTenancy={onTenancy} refresh={refresh} onBucketSelected={refresh} /><main className="content"><div className="topline"><span>Collected {new Date(snapshot.collected_at).toLocaleString()}</span><button className="secondary" onClick={signOut}>Sign out</button></div><nav>{tabs.map((item) => <button className={tab === item ? 'active' : ''} key={item} onClick={() => setTab(item)}>{item}</button>)}</nav>{views[tab]}<footer className="app-footer">OCI IAM Plotter · cached local evidence · read-only OCI collection</footer></main><ChatPopup /></div>; }

function saveBlob(blob, filename) { const href = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = href; link.download = filename; link.click(); URL.revokeObjectURL(href); }

function MarkdownDocument({ source }) {
  const lines = (source || '').split('\n'); const blocks = []; let index = 0;
  const cells = (line) => line.trim().replace(/^\||\|$/g, '').split('|').map((cell) => cell.trim().replaceAll('\\|', '|'));
  while (index < lines.length) {
    const line = lines[index];
    if (!line.trim()) { index += 1; continue; }
    const heading = line.match(/^(#{1,3})\s+(.*)$/);
    if (heading) { const Tag = `h${heading[1].length}`; blocks.push(<Tag key={index}>{heading[2]}</Tag>); index += 1; continue; }
    if (line.startsWith('- ')) { const items = []; while (index < lines.length && lines[index].startsWith('- ')) { items.push(lines[index].slice(2)); index += 1; } blocks.push(<ul key={index}>{items.map((item, itemIndex) => <li key={itemIndex}>{item}</li>)}</ul>); continue; }
    if (line.includes('|') && /^\|?\s*:?-{3,}/.test(lines[index + 1] || '')) { const headers = cells(line); index += 2; const rows = []; while (index < lines.length && lines[index].includes('|') && lines[index].trim()) { rows.push(cells(lines[index])); index += 1; } blocks.push(<div className="table-wrap markdown-table" key={index}><table><thead><tr>{headers.map((cell, cellIndex) => <th key={cellIndex}>{cell}</th>)}</tr></thead><tbody>{rows.map((row, rowIndex) => <tr key={rowIndex}>{headers.map((_, cellIndex) => <td key={cellIndex}>{row[cellIndex] || ''}</td>)}</tr>)}</tbody></table></div>); continue; }
    const paragraph = []; while (index < lines.length && lines[index].trim() && !/^(#{1,3})\s+|^- /.test(lines[index]) && !(lines[index].includes('|') && /^\|?\s*:?-{3,}/.test(lines[index + 1] || ''))) { paragraph.push(lines[index]); index += 1; } blocks.push(<p key={index}>{paragraph.join(' ')}</p>);
  }
  return <article className="markdown-document">{blocks}</article>;
}

function ReleaseNotes({ activeUsers = 0 }) {
  const [open, setOpen] = useState(false);
  return <><div className="release-controls"><button className="release-button" onClick={() => setOpen(true)} title="Open release notes">v1.1.2</button><span className="active-users-indicator" title={`${activeUsers} active users signed in now`} aria-label={`${activeUsers} active users signed in now`}>● {activeUsers}</span></div>{open && createPortal(<div className="modal-backdrop" onClick={() => setOpen(false)}><article className="modal release-modal" onClick={(event) => event.stopPropagation()}><button className="modal-close" onClick={() => setOpen(false)} title="Close release notes">×</button><span className="eyebrow">Release notes</span><h2>Version 1.1.2</h2><p className="subtitle">Released August 11, 2026</p><h3>Key changes</h3><ul><li>Reports &amp; Risks now follows IAM Drift in the primary navigation and is highlighted alongside Access Map.</li><li>The release control now shows the live signed-in user count with a concise hover description.</li><li>Risk Posture includes an in-console score guide covering weights, severity thresholds, and administrator handling.</li><li>Reports &amp; Risks design documentation records the reporting, archive, and scoring logic.</li></ul><p className="notice">This 1.1.2 patch release focuses on clearer navigation and explainable risk posture.</p></article></div>, document.body)}</>;
}

function RiskScoreDocumentation() {
  const [open, setOpen] = useState(false);
  return <><button className="secondary risk-doc-button" onClick={() => setOpen(true)} title="How risk score is calculated">ⓘ Score guide</button>{open && createPortal(<div className="modal-backdrop" onClick={() => setOpen(false)}><article className="modal risk-score-modal" onClick={(event) => event.stopPropagation()}><button className="modal-close" onClick={() => setOpen(false)} title="Close score guide">×</button><span className="eyebrow">Documentation</span><h2>Risk-score calculation</h2><p className="subtitle">Each applicable policy statement is evaluated separately. A user receives the highest statement score, not the sum of all policies.</p><table><thead><tr><th>Evidence</th><th>Points</th></tr></thead><tbody><tr><td><code>manage</code> / <code>use</code> / <code>read</code> / <code>inspect</code></td><td>55 / 25 / 8 / 0</td></tr><tr><td><code>all-resources</code> / sensitive resource</td><td>45 / 30</td></tr><tr><td>Tenancy / compartment scope</td><td>25 / 8</td></tr><tr><td>Condition present</td><td>−10</td></tr></tbody></table><p>Sensitive resources include IAM identity and policy resources, compartments, Vaults, keys, secrets, databases, and tag namespaces. Only scores of 25 or above appear as risk signals.</p><div className="score-levels"><span>Critical 85+</span><span>High 55–84</span><span>Medium 25–54</span><span>Low &lt;25</span></div><p className="notice">For an exact standard <b>Administrators</b> group member, the expected <code>manage all-resources in tenancy</code> grant is excluded. Other permissions are still scored. This is a policy-text prioritization aid, not OCI’s final authorization decision.</p></article></div>, document.body)}</>;
}

function PerUserReportsV110({ entities }) {
  const [users, setUsers] = useState([]), [includeSummary, setIncludeSummary] = useState(true), [result, setResult] = useState(null), [busy, setBusy] = useState(false), [error, setError] = useState('');
  const build = async () => { if (!users.length) return; setBusy(true); setError(''); try { setResult(await json('report', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user_ids: users, format: 'json', include_summary: includeSummary, archive: false }) })); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const download = (format) => { if (!result) return; if (format === 'markdown') return saveBlob(new Blob([result.markdown], { type: 'text/markdown' }), 'oci-iam-user-comparison.md'); if (format === 'html') return saveBlob(new Blob([result.html], { type: 'text/html' }), 'oci-iam-user-comparison.html'); api('report', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user_ids: users, format: 'pdf', include_summary: includeSummary, archive: false }) }).then((response) => response.blob()).then((blob) => saveBlob(blob, 'oci-iam-user-comparison.pdf')).catch((err) => setError(err.message)); };
  return <section><h2>Per-user reports</h2><p className="subtitle">Select one or more users for a holistic, side-by-side evidence report. OCI Generative AI adds an audit-safe narrative and falls back to deterministic evidence when unavailable.</p><div className="controls"><MultiSelect label="Users" value={users} onChange={setUsers} options={entities.filter((item) => item.kind === 'user').map((item) => ({ value: item.id, label: item.name }))} placeholder="Choose users to compare" /><label className="report-summary-toggle"><input type="checkbox" checked={includeSummary} onChange={(event) => setIncludeSummary(event.target.checked)} /> Include OCI Generative AI summaries</label><button onClick={build} disabled={!users.length || busy}>{busy ? 'Building…' : 'Build report'}</button></div>{error && <p className="error">{error}</p>}{result && <div className="report-preview"><div className="report-preview-head"><div><span className="eyebrow">Generated report</span><h3>User access comparison</h3></div><div className="button-row"><button className="secondary" onClick={() => download('html')} title="Download HTML">⌄ HTML</button><button className="secondary" onClick={() => download('markdown')} title="Download Markdown">⌄ MD</button><button className="secondary" onClick={() => download('pdf')} title="Download PDF">⌄ PDF</button></div></div><iframe className="html-report-console" title="Rendered user access report" srcDoc={result.html} /></div>}</section>;
}

function RiskPostureV110() {
  const [result, setResult] = useState(null), [records, setRecords] = useState([]), [selected, setSelected] = useState(null), [all, setAll] = useState(false), [error, setError] = useState(''), [riskLevel, setRiskLevel] = useState(''), [minimumScore, setMinimumScore] = useState(''), [search, setSearch] = useState('');
  const load = () => { json('risk-posture').then(setResult).catch((err) => setError(err.message)); json(`reports/archive?limit=${all ? 100 : 3}`).then((data) => { setRecords(data.records || []); if (data.error) setError(data.error); }).catch((err) => setError(err.message)); };
  useEffect(() => { load(); }, [all]);
  const open = (objectName) => json(`reports/archive/load?object_name=${encodeURIComponent(objectName)}`).then(setSelected).catch((err) => setError(err.message));
  const download = (record, format) => downloadEndpoint(`reports/archive/download?object_name=${encodeURIComponent(record.object_name)}&format=${format}`, `oci-iam-risk-posture.${format === 'markdown' ? 'md' : 'pdf'}`);
  const shown = selected?.risk_posture || result;
  const elements = (shown?.top_risk_elements || []).filter((item) => (!riskLevel || item.level === riskLevel) && (!minimumScore || item.score >= Number(minimumScore)) && (!search.trim() || JSON.stringify(item).toLowerCase().includes(search.trim().toLowerCase())));
  return <section><div className="report-preview-head"><div><span className="eyebrow">All collected users</span><h2>Risk posture</h2></div><div className="button-row"><RiskScoreDocumentation /><button className="secondary" onClick={load} title="Refresh risk posture">↻</button></div></div>{error && <p className="error">{error}</p>}{shown && <><p className="notice">{shown.method} Potential permissions are policy-text signals, not proof of effective authorization.</p><div className="metric-grid clickable-metrics">{Object.entries(shown.distribution || {}).map(([level, count]) => <button className={`metric risk-${level} ${riskLevel === level ? 'selected' : ''}`} onClick={() => setRiskLevel((current) => current === level ? '' : level)} key={level} title={`Filter ${title(level)} risk users`}><strong>{count}</strong><span>{title(level)} risk users</span></button>)}</div><div className="controls"><label>Risk level<select value={riskLevel} onChange={(event) => setRiskLevel(event.target.value)}><option value="">All risk levels</option>{Object.keys(shown.distribution || {}).map((level) => <option value={level} key={level}>{title(level)}</option>)}</select></label><label>Minimum score<input type="number" min="0" value={minimumScore} onChange={(event) => setMinimumScore(event.target.value)} placeholder="Any score" /></label><label>Search risk evidence<input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="User, permission, or reason" /></label><button className="secondary" onClick={() => { setRiskLevel(''); setMinimumScore(''); setSearch(''); }}>Clear filters</button></div><h3>{selected ? 'Selected archived posture' : 'Current top risk signals'} <span className="subtitle">· {elements.length} shown</span></h3>{elements.length ? <DataTable rows={elements.map((item) => ({ user: item.user, risk: item.level, score: item.score, permission: item.permission, why: item.reasons.join('; ') }))} columns={['user', 'risk', 'score', 'permission', 'why']} /> : <div className="empty compact">No risk signals match these filters.</div>}</>}<section className="report-archive"><div className="report-preview-head"><div><span className="eyebrow">Object Storage</span><h3>Collection risk reports</h3></div><button className="secondary" onClick={() => setAll((value) => !value)}>{all ? 'Latest 3' : 'Browse all'}</button></div><p className="subtitle">The latest three reports for this tenancy are shown by default. A risk posture report is created after every collection.</p>{records.length ? <DataTable rows={records.map((record, index) => ({ latest: index === 0 && !all ? 'Latest' : '', created: new Date(record.created_at).toLocaleString(), view: <button className="icon" onClick={() => open(record.object_name)} title="Open report">◉</button>, markdown: <button className="icon" onClick={() => download(record, 'markdown')} title="Download Markdown">⌄</button>, pdf: <button className="icon" onClick={() => download(record, 'pdf')} title="Download PDF">▣</button> }))} columns={['latest', 'created', 'view', 'markdown', 'pdf']} /> : <div className="empty compact">No archived risk posture reports are available yet.</div>}</section></section>;
}

function ReportsAndRisks({ entities }) { const [tab, setTab] = useState('reports'); return <><div className="report-subtabs"><button className={tab === 'reports' ? 'active' : 'secondary'} onClick={() => setTab('reports')}>Per-user reports</button><button className={tab === 'risk' ? 'active' : 'secondary'} onClick={() => setTab('risk')}>Risk posture</button></div>{tab === 'reports' ? <PerUserReportsV110 entities={entities} /> : <RiskPostureV110 />}</>; }

function WorkspaceV110({ snapshot, entities, history, tenancies, activeTenancy, onTenancy, refresh, signOut }) { const tabs = ['Access Map', 'Inventory', 'IAM drift', 'Reports & Risks', 'User analysis', 'Policy statements', 'Duplicates', 'Collection logs']; const [tab, setTab] = useState('Access Map'); const views = { 'Access Map': <Investigate entities={entities} />, Inventory: <Inventory snapshot={snapshot} entities={entities} />, 'IAM drift': <Drift />, 'User analysis': <Users entities={entities} />, 'Policy statements': <Policies />, Duplicates: <Duplicates />, 'Reports & Risks': <ReportsAndRisks entities={entities} />, 'Collection logs': <CollectionLogs /> }; return <div className="shell"><ReleaseNotes activeUsers={snapshot.active_portal_users || 0} /><Sidebar snapshot={snapshot} history={history} tenancies={tenancies} activeTenancy={activeTenancy} onTenancy={onTenancy} refresh={refresh} onBucketSelected={refresh} /><main className="content"><div className="topline"><span>Collected {new Date(snapshot.collected_at).toLocaleString()}</span><button className="secondary" onClick={signOut}>Sign out</button></div><nav>{tabs.map((item) => <button className={tab === item ? 'active' : ''} key={item} onClick={() => setTab(item)}>{item}{(item === 'Access Map' || item === 'Reports & Risks') && <span className="focus-star" title="Focus area" aria-label="Focus area">★</span>}</button>)}</nav>{views[tab]}<footer className="app-footer">OCI IAM Plotter · cached local evidence · read-only OCI collection</footer></main><ChatPopup /></div>; }

Workspace = WorkspaceV110;

function MapOnly() { const [data, setData] = useState(null); useEffect(() => { try { setData(JSON.parse(localStorage.getItem('oci-iam-plotter-active-map') || 'null')); } catch { setData(null); } }, []); return <main className="map-only"><div className="hero"><span className="eyebrow">Focused connection map</span><h1>OCI IAM Plotter</h1><p>Drag to pan, scroll to zoom, and drag nodes to refine the layout.</p></div>{data ? <Map data={data} standalone /> : <div className="empty">No focused map is available. Open this window from an investigation map.</div>}</main>; }
function App() { const [authenticated, setAuthenticated] = useState(null); const [snapshot, setSnapshot] = useState(null); const [entities, setEntities] = useState([]); const [history, setHistory] = useState([]); const [tenancies, setTenancies] = useState([]); const [activeTenancy, setActiveTenancy] = useState(''); const mapOnly = new URLSearchParams(window.location.search).has('mapOnly'); const load = async () => { try { const me = await json('me'); setAuthenticated(me.authenticated); if (!me.authenticated) return; const tenancyResult = await json('tenancies'); setTenancies(tenancyResult.tenancies); setActiveTenancy(tenancyResult.active_tenancy_id || ''); if (!tenancyResult.active_tenancy_id) { setSnapshot(null); setEntities([]); setHistory([]); return; } const current = await json('snapshot'); setSnapshot(current); const values = await json('entities?limit=1000'); setEntities(values); const prior = await json('history'); setHistory(prior.records); } catch { setSnapshot(null); } }; const selectTenancy = async (tenancyId) => { await json('tenancies/select', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ tenancy_id: tenancyId }) }); await load(); }; const signOut = async () => { await json('logout', { method: 'POST' }); setAuthenticated(false); setSnapshot(null); setTenancies([]); }; useEffect(() => { if (!mapOnly) load(); }, [mapOnly]); if (mapOnly) return <MapOnly />; if (authenticated === null) return <div className="loading">Loading OCI IAM Plotter…</div>; if (!authenticated) return <Login onReady={load} />; if (!snapshot) return <div className="shell"><Sidebar snapshot={null} history={history} tenancies={tenancies} activeTenancy={activeTenancy} onTenancy={selectTenancy} refresh={load} onBucketSelected={load} /><main className="content"><div className="topline"><span>Read-only identity intelligence</span><button className="secondary" onClick={signOut}>Sign out</button></div><div className="hero"><span className="eyebrow">Start here</span><h1>OCI IAM Plotter</h1><p>Collect a normalized IAM snapshot from the sidebar. The full investigation, map, drift, reporting, and evidence workspaces will appear as soon as collection completes.</p></div></main></div>; return <Workspace key={activeTenancy} snapshot={snapshot} entities={entities} history={history} tenancies={tenancies} activeTenancy={activeTenancy} onTenancy={selectTenancy} refresh={load} signOut={signOut} />; }

createRoot(document.getElementById('root')).render(<App />);
